// generator, not this file.
//
// Reads triangles from stdin, one per line:
//
//   TRI x0 y0 x1 y1 x2 y2 r g b
//
// Each triangle is rendered in its own frame by the production melonDS
// software rasteriser; one 256x192 RGBA word buffer is written
// per triangle.
#include <cstdio>
#include <cstdlib>
#include <cstring>
#include <memory>
#include <vector>

#include "NDS.h"
#include "GPU.h"
#include "GPU3D.h"
#include "GPU3D_Soft.h"
#include "GPU_Soft.h"

using namespace melonDS;

struct Tri
{
    s32 x[3];
    s32 y[3];
    u32 color;
    bool facing;
};

static bool readTri(Tri& tri)
{
    char kind[5];
    if (std::scanf("%4s", kind) != 1) return false;
    if (std::strcmp(kind, "TRI") != 0) return false;
    unsigned r, g, b;
    if (std::scanf("%d %d %d %d %d %d %u %u %u",
            &tri.x[0], &tri.y[0], &tri.x[1], &tri.y[1],
            &tri.x[2], &tri.y[2], &r, &g, &b) != 9)
        return false;
    int face = 1;
    if (std::scanf("%d", &face) != 1) face = 1;
    tri.facing = face != 0;
    tri.color = (r & 63) | ((g & 63) << 6) |
        ((b & 63) << 12);
    return true;
}

int main()
{
    auto ndsHolder = std::make_unique<NDS>();
    NDS& nds = *ndsHolder;
    auto softHolder = std::make_unique<SoftRenderer>(nds);
    SoftRenderer& soft = *softHolder;
    SoftRenderer3D* r3d = soft.Get3DRenderer();
    GPU3D& gpu3d = nds.GPU.GPU3D;

    u32 dispcnt = 0;
    if (const char* env = std::getenv("ORACLE_DISPCNT"))
        dispcnt = static_cast<u32>(std::strtoul(env, nullptr, 0));
    gpu3d.RenderDispCnt = dispcnt;
    gpu3d.RenderAlphaRef = 0;
    gpu3d.RenderClearAttr1 = 0;
    gpu3d.RenderClearAttr2 = 0;
    gpu3d.RenderXPos = 0;

    std::vector<Tri> tris;
    Tri tri;
    while (readTri(tri)) tris.push_back(tri);

    Vertex vertices[3];
    Polygon polygon;

    for (const Tri& t : tris)
    {
        Polygon& p = polygon;
        p.NumVertices = 3;
        p.Attr = 31 << 16;
        p.TexParam = 0;
        p.TexPalette = 0;
        p.Degenerate = false;
        p.FacingView = t.facing;
        p.WBuffer = false;
        p.Translucent = false;
        p.IsShadowMask = false;
        p.IsShadow = false;
        p.Type = 0;
        p.SortKey = 0;

        s32 ytop = 192, ybot = 0;
        s32 xtop = 256, xbot = 0;
        u32 vtop = 0, vbot = 0;
        for (u32 v = 0; v < 3; ++v)
        {
            Vertex& vert = vertices[v];
            vert.FinalPosition[0] = t.x[v];
            vert.FinalPosition[1] = t.y[v];
            vert.FinalColor[0] = (t.color & 63);
            vert.FinalColor[1] = ((t.color >> 6) & 63);
            vert.FinalColor[2] = ((t.color >> 12) & 63);
            p.Vertices[v] = &vert;
            p.FinalZ[v] = 0;
            p.FinalW[v] = 0;
            if (t.y[v] < ytop) { ytop = t.y[v]; xtop = t.x[v]; vtop = v; }
            if (t.y[v] > ybot || (t.y[v] == ybot && t.x[v] > xbot))
            { ybot = t.y[v]; xbot = t.x[v]; vbot = v; }
        }
        p.YTop = ytop;
        p.YBottom = ybot;
        p.VTop = vtop;
        p.VBottom = vbot;
        p.XTop = xtop;
        p.XBottom = xbot;

        Polygon* ptr = &p;
        r3d->RenderFrame(&ptr, 1);

        for (u32 y = 0; y < 192; ++y)
            std::fwrite(r3d->GetLine(static_cast<int>(y)),
                sizeof(u32), 256, stdout);
    }
    return 0;
}
